// Üretilen dosya: tool/ozgun/uret.py. Bilişim ve Algoritmalar · Sıralama ve arama algoritmaları uygulamalı (zor).
const ozComputing7Zor = <(String, String, List<String>, String)>[
  ('Sıralı bir dizide değer bulunamadığında ikili aramanın −(ekleme_yeri) − 1 döndürmesi (Java\'daki Arrays.binarySearch gibi) hangi amaca hizmet eder?', 'Hem bulunamadığını bildirir hem de değerin ekleneceği yeri taşır', ['Dizinin uzunluğunu çağırana iletir', 'Aramanın kaç adım sürdüğünü çağırana negatif sayı olarak gösterir', 'Dizinin sıralı olmadığını haber verir'], 'Sonuç negatif olduğu için \'yok\' anlamı taşır; çağıran −sonuç − 1 hesaplayarak sırayı bozmayacak ekleme konumunu elde eder. −1 eklenmesi, 0 konumunu da negatif yapmak içindir.'),
  ('Yüklemin doğru olduğu son konumu arayan ve \'alt ← orta\' güncellemesini kullanan bir ikili aramada orta indis neden ⌈(alt + üst)/2⌉ biçiminde yukarı yuvarlanır?', 'Aksi hâlde iki elemanlı aralıkta orta = alt olur ve aralık daralmaz', ['Aşağı yuvarlama negatif indis üretir', 'Yukarı yuvarlama karşılaştırma sayısını her durumda yarıya indirdiği için', 'Aşağı yuvarlama yalnız tek sayıda elemanla çalışır'], 'alt + 1 = üst iken aşağı yuvarlanan orta, alt\'a eşit çıkar; \'alt ← orta\' hiçbir şeyi değiştirmez ve döngü sonsuza gider. Yukarı yuvarlama orta = üst verir.'),
  ('Döndürülmüş 15, 18, 2, 3, 6, 12 dizisinde 3 değeri, sıralı yarıyı belirleyip ona göre daralan ikili aramayla aranıyor (orta = ⌊(alt + üst)/2⌋, indisler 0\'dan). Ortada sırasıyla hangi elemanlara bakılır?', '2, 6, 3', ['2, 12, 3', '18, 3', '2, 3'], '0–5 aralığında orta eleman 2\'dir; sağ yarı (2…12) sıralı ve 3 bu yarıda olduğundan alt = 3 olur. 3–5\'te orta 6\'dır; sol yarı 3, 6 sıralı ve 3 içinde, üst = 3 olur. Son orta eleman 3\'tür.'),
  ('Döndürülmüş sıralı dizide yinelenen değerler bulunabiliyorsa (ör. 2, 2, 2, 3, 2) arama neden en kötü durumda doğrusal süreye düşer?', 'Alt, orta ve üst eleman eşit olunca hangi yarının sıralı olduğu anlaşılamaz', ['Yinelenen değerler dizinin baştan sona sıralı kalmasını engellediği için', 'Ortadaki eleman hiçbir zaman hedefe eşit olamaz', 'İkili arama eşit değerleri karşılaştıramaz'], 'Üç uç da eşitse kırılma noktası iki yarıdan birinde olabilir; algoritma ancak sınırları birer birer daraltabilir ve bu en kötü durumda n adım sürer.'),
  ('Üçlü aramayla en büyük değeri aranan bir fonksiyonun geniş bir bölgede sabit (düz) olması neden sorun yaratır?', 'İki iç nokta eşit çıkınca tepenin hangi yanda olduğu anlaşılamaz', ['Düz bölgede fonksiyon değeri hesaplanamaz hâle gelir ve program durur', 'Aralığın uzunluğu her adımda artar', 'Algoritma yalnız negatif değerlerde çalışır'], 'Kesin tek tepelilik varsayımı bozulur: f(m1) = f(m2) olduğunda tepe soldaki, ortadaki ya da sağdaki parçada olabilir ve yanlış parça atılabilir.'),
  ('Fibonacci araması bir aralığı her adımda yaklaşık hangi oranlarda iki parçaya ayırır?', 'Yaklaşık %38 ve %62', ['Tam %50 ve %50', 'Her adımda rastgele seçilen oranlarda', 'Yaklaşık %10 ve %90'], 'Ardışık Fibonacci sayılarının oranı altın orana yaklaşır; bu yüzden bölme noktası aralığı kabaca 0,382 ve 0,618 oranlarında ayırır.'),
  ('10 elemanlı sıralı bir dizide (indisler 0–9) Fibonacci araması başlıyor. Algoritma 10\'dan küçük olmayan en küçük Fibonacci sayısını (13) alıyor ve ilk karşılaştırmayı −1 + 5 konumunda yapıyor. İlk bakılan indis kaçtır?', '4', ['5', '6', '3'], '13 = 8 + 5 olduğundan ilk bölme bir önceki iki Fibonacci sayısından küçük olanıyla (5) yapılır; başlangıç kaydırması −1 olduğundan indis −1 + 5 = 4\'tür.'),
  ('Eklemeli sıralamanın çalışma süresi, sıralanacak listedeki ters çift (birbirine göre yanlış sırada duran eleman çifti) sayısı k ile n\'ye bağlı olarak nasıl ifade edilir?', 'n + k ile orantılı', ['n · k ile orantılı', 'n log n ile orantılı, k\'dan bağımsız', 'Yalnız k² ile orantılı'], 'Her kaydırma tam bir ters çifti ortadan kaldırır, ayrıca her eleman en az bir karşılaştırma yapar. Bu yüzden süre O(n + k)\'dır ve neredeyse sıralı listelerde doğrusala yaklaşır.'),
  ('Boşlukların hep 2\'nin kuvveti seçildiği (8, 4, 2, 1 gibi) Shell sıralaması neden kötü sonuç verebilir?', 'Tek ve çift konumlardaki elemanlar son tura kadar hiç karşılaştırılmaz', ['2\'nin kuvvetleri tek sayıda elemanlı dizilerde tanımsız olduğu için algoritma durur', 'Bu boşluklar her turda diziyi ters çevirir', 'Bu boşluklarla dizi asla sıralanamaz'], 'Bütün boşluklar çiftse, son tur dışında tek ve çift indisler ayrı gruplarda kalır. Örneğin büyük değerler tek, küçükler çift konumdaysa son tur karesel iş yapmak zorunda kalır.'),
  ('Marcin Ciura\'nın 2001\'de deneysel olarak bulduğu ve Shell sıralamasında çok iyi sonuç verdiği bilinen boşluk dizisi hangisiyle başlar?', '1, 4, 10, 23, 57, 132, 301, 701', ['1, 2, 4, 8, 16, 32, 64, 128', '1, 3, 7, 15, 31, 63, 127, 255', '1, 4, 13, 40, 121, 364, 1093, 3280'], 'Ciura dizisi bir formülle değil deneylerle bulunmuştur. Diğer seçenekler sırasıyla 2\'nin kuvvetleri, Hibbard (2ᵏ − 1) ve Knuth (3h + 1) dizileridir.'),
  ('Yukarıdan aşağı birleştirmeli sıralama 8 elemanlı bir diziyi sıralarken en kötü durumda toplam kaç eleman karşılaştırması yapar?', '17', ['24', '28', '12'], 'En kötü durumda birleştirme düzeylerinde 4·1 + 2·3 + 1·7 = 17 karşılaştırma yapılır; bu, n log₂ n − n + 1 = 24 − 8 + 1 formülüyle de bulunur.'),
  ('Ters çiftler birleştirmeli sıralamayla sayılırken, birleştirme sırasında sağ diziden bir eleman alındığında sol dizide kalan eleman sayısı sayaca eklenir. Sol [2, 5, 8] ve sağ [1, 3, 9] birleştirilirken kaç ters çift sayılır?', '5', ['3', '6', '9'], '1 alınırken solda 3 eleman (2, 5, 8) kalmıştır; 3 alınırken 2 eleman (5, 8) kalmıştır; 9 alınırken solda eleman kalmamıştır. 3 + 2 = 5.'),
  ('Hızlı sıralamada Lomuto bölümlemesi son elemanı pivot alır. 2, 8, 7, 1, 3, 5, 6, 4 dizisine bu bölümleme uygulanınca (küçük ya da eşitler sola alınarak) dizi nasıl olur?', '2, 1, 3, 4, 7, 5, 6, 8', ['2, 1, 3, 4, 8, 7, 5, 6', '1, 2, 3, 4, 5, 6, 7, 8', '2, 3, 1, 4, 7, 6, 5, 8'], '4\'ten küçük olan 2, 1, 3 sırayla sol bölgeye takas edilir; sağda 7, 5, 6, 8 kalır. En sonda pivot (4) sol bölgenin hemen sağına, 3 numaralı indise konur.'),
  ('Bütün elemanları birbirine eşit olan bir dizide Lomuto bölümlemesi kullanan hızlı sıralama neden karesel süreye düşer?', 'Her bölümleme bütün elemanları bir tarafa bırakır ve öbür taraf boş kalır', ['Eşit elemanlar birbiriyle karşılaştırılamadığı için aynı döngü defalarca tekrarlanır', 'Pivot her seferinde dizinin ortasına yerleşir', 'Eşit elemanlar diziden silinir ve dizi yeniden kurulur'], 'Her eleman pivottan \'küçük ya da eşit\' sayıldığı için sol bölgeye gider ve pivot en sağda kalır; özyineleme her seferinde yalnız bir eleman azalmış diziyle çalışır.'),
  ('Hoare bölümlemesi ilk elemanı (5) pivot alıyor; soldan pivottan küçük olmayan, sağdan pivottan büyük olmayan ilk elemanları bulup takas ediyor ve işaretçiler kesişince duruyor. 5, 3, 8, 4, 9, 1, 6, 2, 7 dizisinde bölümleme bitince dizi nasıl olur?', '2, 3, 1, 4, 9, 8, 6, 5, 7', ['1, 3, 2, 4, 5, 8, 6, 9, 7', '2, 3, 1, 4, 5, 9, 8, 6, 7', '4, 3, 2, 1, 5, 9, 8, 6, 7'], 'Önce 5 ile 2, sonra 8 ile 1 takas edilir. Ardından soldaki işaretçi 9\'da, sağdaki 4\'te durur ve kesiştikleri için işlem biter; sol bölüm 2, 3, 1, 4, sağ bölüm 9, 8, 6, 5, 7\'dir.'),
  ('Bütün elemanları eşit olan bir dizide Hoare bölümlemesi, Lomuto\'dan farklı olarak neden dengeli parçalar üretir?', 'İşaretçiler pivota eşit elemanlarda da durup takas yaptığından ortada buluşurlar', ['Eşit elemanları diziden çıkarıp sayarak ayrı bir yerde tutar', 'Eşit elemanlarda takası tamamen atlayıp diziyi indis olarak doğrudan tam ortadan ikiye böldüğü için', 'Pivotu her seferinde rastgele seçip eşitliği bozar'], 'Soldaki işaretçi \'küçük olmayan\', sağdaki \'büyük olmayan\' elemanda durur; eşit dizide her adımda iki işaretçi de durur, takas yapar ve birer adım ilerler. Böylece ortada buluşur.'),
  ('Çok büyük dizilerde hızlı sıralama için kullanılan \'dokuzlu\' (Tukey\'in ninther) pivot seçimi nasıl çalışır?', 'Dokuz eleman üçerli gruplanır, her grubun ortancası alınır ve bu üç ortancanın ortancası pivot olur', ['Dizinin ilk dokuz elemanı sıralanır ve en büyüğü pivot olur', 'Dokuz kez rastgele eleman seçilir ve ortalamaları pivot olur', 'Dizi dokuz eşit parçaya bölünür, her parça ayrı bir pivotla sıralanır ve parçalar en sonda birleştirilir'], 'Ninther, gerçek ortancaya üçün ortancasından daha iyi yaklaşır ve yalnız birkaç ek karşılaştırma ister.'),
  ('Yığın sıralaması 4, 10, 3, 5, 1 dizisinden aşağıdan yukarı yöntemle bir max-yığın kuruyor (dizi gösteriminde i\'nin çocukları 2i + 1 ve 2i + 2). Kurulum bitince dizi nasıl olur?', '10, 5, 3, 4, 1', ['10, 4, 3, 5, 1', '10, 5, 4, 3, 1', '1, 3, 4, 5, 10'], 'Önce 1 numaralı düğüm (10) denetlenir, çocukları 5 ve 1\'den büyüktür. Sonra kök 4, büyük çocuğu 10 ile yer değiştirir; aşağı inen 4, çocuğu 5 ile yer değiştirir.'),
  ('Max-yığın hâlindeki 10, 5, 3, 4, 1 dizisine yığın sıralamasının ilk adımı uygulanıyor: kök son elemanla takas ediliyor ve yığın bir eleman küçültülüp kök aşağı süzülüyor. Adım sonunda dizi nasıldır?', '5, 4, 3, 1, 10', ['1, 5, 3, 4, 10', '5, 1, 3, 4, 10', '4, 5, 3, 1, 10'], 'Takastan sonra 1, 5, 3, 4 | 10 olur. 1 büyük çocuğu 5 ile, ardından çocuğu 4 ile yer değiştirir: 5, 4, 3, 1 | 10.'),
  ('Medyanların medyanı yönteminde 5\'li gruplarla seçilen pivot, gruplardaki elemanların yaklaşık en az ne kadarından büyük, ne kadarından küçüktür?', 'Yaklaşık %30\'undan', ['Yaklaşık %50\'sinden', 'Yaklaşık %10\'undan', 'Yaklaşık %90\'ından'], 'Grup ortancalarının yarısı pivottan küçüktür ve bu grupların her birinde en az 3 eleman ortancadan küçüktür; bu da yaklaşık 3n/10 eleman eder. Böylece her adımda en fazla yaklaşık %70\'lik kısım kalır.'),
  ('Medyanların medyanı yönteminde gruplar 5 yerine 3\'er elemanlı seçilirse ne olur?', 'Her adımda atılan kısım az kaldığından doğrusal süre garantisi kaybolur', ['Algoritma yanlış eleman döndürmeye başlar', 'Süre doğrusalın da altına, her durumda log n mertebesine iner', 'Grupların ortancası artık hesaplanamaz'], '3\'lü gruplarla pivot yaklaşık n/3 elemandan büyük olur; özyineleme denklemindeki parçaların toplamı n\'ye eşit kalır (n/3 + 2n/3) ve süre n log n mertebesine çıkar.'),
  ('Sayma sıralamasının kararlı olması için girdi, birikimli sayaçlarla yerleştirme aşamasında neden sondan başa doğru taranır?', 'Her değerin son kopyası, o değere ayrılan bölgenin sonuna yerleşsin diye', ['Sondan başa tarama sayaç dizisini daha az bellekle tutmayı sağladığı için', 'Baştan tarama sırasında sayaçlar negatif olacağından program çöktüğü için', 'Sondan başa tarama karşılaştırma sayısını sıfıra indirdiği için'], 'Sayaç her yerleştirmede azaltılır, yani bölge sağdan sola dolar. Girdi de sondan başa okununca eşit anahtarlı elemanlar başlangıçtaki sıralarını korur.'),
  ('Taban sıralaması 329, 457, 657, 839, 436, 720, 355 dizisine uygulanıyor. Birler basamağına göre kararlı geçişten sonra dizi 720, 355, 436, 457, 657, 329, 839 oluyor. Onlar basamağına göre ikinci geçişten sonra dizi nasıl olur?', '720, 329, 436, 839, 355, 457, 657', ['329, 355, 436, 457, 657, 720, 839', '720, 329, 839, 436, 355, 457, 657', '720, 329, 436, 839, 355, 657, 457'], 'Onlar basamakları 2, 2, 3, 3, 5, 5, 5\'tir. Kararlı sıralamada 2\'liler (720, 329) ve 3\'lüler (436, 839) ile 5\'liler (355, 457, 657) önceki sıralarını korur.'),
  ('Stooge sıralaması dizinin ilk 2/3\'ünü, son 2/3\'ünü ve yeniden ilk 2/3\'ünü özyinelemeli olarak sıralar. Bu algoritmanın süresi yaklaşık hangi mertebededir?', 'n^2,71', ['n log n', 'n²', 'n³'], 'T(n) = 3T(2n/3) + O(1) denkleminin çözümü n^(log 3 / log 1,5) ≈ n^2,71\'dir; bu, kabarcık sıralamasından bile yavaştır.'),
  ('4 girdiyi her durumda sıralayan bir sıralama ağı için gereken en az karşılaştırıcı sayısı kaçtır?', '5', ['4', '6', '3'], 'Örneğin (1,2), (3,4), (1,3), (2,4), (2,3) karşılaştırıcıları 4 girdiyi sıralar; 4 karşılaştırıcıyla bunun yapılamayacağı kanıtlanmıştır (4! = 24 > 2⁴ = 16).'),
  ('Bitonik 1, 4, 6, 8, 7, 5, 3, 2 dizisinin birleştirilmesinin ilk adımında her i için i. eleman ile (i + 4). eleman karşılaştırılıp küçüğü sol yarıya, büyüğü sağ yarıya yazılıyor. Sonuçta sol yarı hangisidir?', '1, 4, 3, 2', ['1, 2, 3, 4', '7, 5, 6, 8', '1, 5, 3, 2'], 'Çiftler (1, 7), (4, 5), (6, 3), (8, 2)\'dir; küçükler sırayla 1, 4, 3, 2, büyükler 7, 5, 6, 8\'dir. Sol yarının her elemanı sağ yarının her elemanından küçüktür ve iki yarı da yine bitoniktir.'),
  ('Değerleri üstel artan 2, 4, 8, 16, 32, 64, 128 dizisinde (indisler 0–6) 64 değeri interpolasyon aramasıyla aranıyor; tahmin aşağı yuvarlanıyor. Değer kaçıncı denemede bulunur?', '3. denemede', ['1. denemede', '2. denemede', '6. denemede'], 'İlk tahmin 0 + 62·6/126 ≈ 2,95 → 2 (değer 8); sonra 3 + 48·3/112 ≈ 4,3 → 4 (değer 32); sonra 5 + 0 = 5 (değer 64). Düzgün olmayan dağılım tahminleri hep hedefin gerisine düşürür.'),
  ('Turnuva sıralaması (tournament sort) şampiyonu çıktıya yazdıktan sonra bir sonraki elemanı nasıl bulur?', 'Şampiyonun yaprağını boşaltıp yalnız onun köke giden yolu üzerindeki maçları yeniden oynatır', ['Turnuvayı kalan bütün elemanlarla baştan başlatıp her seferinde n − 1 maç daha oynatır ve kazananı alır', 'Kalan elemanları kabarcık sıralamasıyla sıralayıp ilkini alır', 'Şampiyonla ilk turda karşılaşan oyuncuyu doğrudan ikinci kabul eder'], 'Kazananlar ağacında şampiyonun çıktığı yaprak eksi sonsuz (ya da boş) yapılır ve yalnız o yoldaki log n maç tekrarlanır; böylece toplam süre n log n olur.'),
  ('Timsort\'ta iki koşu birleştirilirken bir koşudan art arda çok sayıda eleman seçiliyorsa algoritma \'dörtnala\' (galloping) moduna geçer. Bu modda ne yapılır?', 'Öbür koşunun elemanının yeri üstel aramayla bulunup blok hâlinde kopyalanır', ['Birleştirme tamamen durdurulur ve iki koşu baştan eklemeli sıralamayla yeniden sıralanır', 'Kazanan koşunun elemanları rastgele seçilerek çıktıya yazılır', 'Karşılaştırmalar bırakılıp koşular olduğu gibi uç uca eklenir'], 'Tek tek karşılaştırmak yerine 1, 3, 7, … adımlarla atlanıp sonra ikili arama yapılır; büyük blokların birleştirilmesinde karşılaştırma sayısı ciddi biçimde azalır.'),
  ('Java\'da Collections.sort çalışırken \'Comparison method violates its general contract!\' hatası alınıyor. En olası neden hangisidir?', 'Karşılaştırıcı tutarsız sonuç veriyor', ['Liste çok sayıda eleman içeriyor ve bellek yetmiyor', 'Listede birbirine eşit elemanlar bulunuyor', 'Liste daha önce sıralanmış ve yeniden sıralanamıyor'], 'Timsort karşılaştırıcının kurallara uyduğunu varsayar; örneğin compare(a, b) ve compare(b, a) aynı işareti verirse ya da geçişlilik bozulursa bu tutarsızlığı fark edip istisna fırlatabilir.'),
  ('Kayan noktalı sayıların bulunduğu bir dizide NaN (\'sayı değil\') değeri varsa sıradan \'<\' karşılaştırmasıyla sıralama neden güvenilmez olur?', 'NaN ile yapılan her \'<\' karşılaştırması yanlış çıktığından sıra tutarlılığı bozulur', ['NaN en büyük sayı kabul edilip her zaman listenin sonuna yerleştiği için aslında sorun yaratmaz', 'NaN bulunan dizi bellekte sabit boyutlu tutulamaz ve kopyalanamaz', 'NaN değeri sıralama sırasında sıfıra dönüştürülür ve kaybolur'], 'NaN < x ve x < NaN ikisi de yanlıştır; NaN her sayıya \'eşit\' gibi davranır ama sayılar birbirine eşit değildir. Geçişlilik bozulur ve sonuç algoritmaya göre değişir.'),
  ('Dış sıralamada ilk koşular oluşturulurken \'yerine koyma seçimi\' (replacement selection) kullanılırsa, rastgele girdide koşuların ortalama uzunluğu ne olur?', 'Belleğin yaklaşık iki katı', ['Belleğin yaklaşık yarısı', 'Belleğe tam olarak eşit', 'Dosyanın tamamı'], 'Bellekteki yığından en küçük eleman yazılır ve yerine yeni bir eleman okunur; yeni eleman son yazılandan büyükse aynı koşuya katılabilir. Bu sayede koşular ortalamada belleğin iki katı uzunlukta olur ve tur sayısı azalır.'),
  ('Manyetik bant dönemine ait \'çok fazlı birleştirme\' (polyphase merge) yönteminin amacı neydi?', 'Az sayıda bant sürücüsüyle bantları boşta bırakmadan birleştirme yapmak', ['Bantlardaki verileri birleştirmeden önce sıkıştırıp yer açmak', 'Her bandı birden çok işlemciye eş zamanlı olarak okutmak', 'Bantlarda kalan bozuk kayıtları birleştirme sırasında onarmak'], 'Koşular bantlara Fibonacci sayılarına uygun oranlarda dağıtılır; her aşamada bir bant boşalır ve çıktı bandı olur. Böylece eşit dağılımlı yönteme göre daha az bantla daha az kopyalama yapılır.'),
  ('Hem kararlı, hem yerinde, hem de en kötü durumda n log n sürede çalışan sıralama algoritmaları (ör. WikiSort, GrailSort) hangi genel teknik ailesine dayanır?', 'Blok birleştirme (block merge) sıralaması', ['Kova sıralaması', 'Sıralama ağları', 'Rastgele karıştırmaya dayalı sıralama'], 'Blok sıralaması, birleştirmeyi diziyi √n boyutlu bloklara ayırıp blokları döndürerek ek dizi olmadan yapar; üç özelliği birlikte sağlar ama karmaşıktır ve sabit çarpanları büyüktür.'),
  ('40 sayıdan oluşan bir kümede toplamı tam olarak verilen bir değere eşit alt küme aranıyor. \'Ortada buluşma\' yöntemi kümeyi ikiye bölüp bir yarının bütün alt küme toplamlarını sıralar; öteki yarının her toplamı için ne yapılır?', 'Gereken tamamlayıcı toplam, sıralı listede ikili aramayla aranır', ['Sıralı listenin tamamı baştan sona doğrusal olarak taranır', 'Toplam, sıralı listenin ortancasıyla karşılaştırılıp atılır', 'İki yarı birleştirilip bütün 2⁴⁰ alt küme yeniden denenir'], 'Her yarı 2²⁰ ≈ 1 milyon alt küme toplamı verir. Bir yarı sıralanıp öbür yarının her toplamı için hedef − toplam ikili aramayla aranır; 2⁴⁰ denemenin yerini yaklaşık 2²⁰ · 20 işlem alır.'),
  ('Boyer–Moore–Horspool algoritmasında \'KALEM\' kalıbı için kaydırma tablosu, kalıbın son karakteri hariç her karakterin sona uzaklığıyla doldurulur. Metinde kalıbın son konumuna \'A\' harfi denk gelip uyuşmazlık olursa kalıp kaç konum kaydırılır?', '3', ['1', '5', '4'], '\'A\', kalıbın 1 numaralı indisindedir (0\'dan); kaydırma m − 1 − 1 = 5 − 2 = 3\'tür. Bu kaydırma, metindeki \'A\'yı kalıptaki \'A\' ile hizalar.'),
  ('Z-algoritması bir dizgenin her konumundan başlayan ve dizgenin öneki ile eşleşen en uzun parçanın uzunluğunu hesaplar. \'aabxaab\' dizgesinde 0\'dan sayılan 4 numaralı konumun Z değeri kaçtır?', '3', ['2', '4', '7'], '4. konumdan başlayan \'aab\', dizgenin başındaki \'aab\' ile eşleşir; sonrasında dizge biter. Bu yüzden Z[4] = 3\'tür.'),
  ('1024 elemanlı sırasız bir listede arama yapılacak. Sıralama yaklaşık 10 240 karşılaştırma, her ikili arama 10, her doğrusal arama ise ortalama 512 karşılaştırma tutuyorsa, yaklaşık kaç aramadan sonra önce sıralamak daha kârlı hâle gelir?', 'Yaklaşık 21 arama', ['Yaklaşık 2 arama', 'Yaklaşık 512 arama', 'Yaklaşık 10 240 arama'], 'k arama için doğrusal maliyet 512k, sıralı yaklaşım 10 240 + 10k\'dır. 512k > 10 240 + 10k eşitsizliği k ≥ 21 için sağlanır.'),
  ('Sıralı bir dizide her değer tam iki kez geçiyor, yalnız biri bir kez geçiyor: 1, 1, 2, 2, 3, 4, 4. Tek geçen değeri O(log n) sürede bulmak için ikili arama hangi gözleme dayanır?', 'Tek elemandan önce çiftler çift indiste başlar, sonra tek indiste başlar', ['Tek eleman her zaman dizinin en büyük değeridir', 'Tek elemanın indisi her zaman dizinin uzunluğuna eşittir', 'Çiftlerin toplamı tek elemana eşit olduğu için dizinin iki yarısının toplamına bakmak yeterlidir'], 'Tek elemandan önce her çiftin ilki çift indistedir; tek eleman bu düzeni bir kaydırır. Ortadaki çift indisli eleman kendinden sonrakine eşitse tek eleman sağdadır. Bu örnekte sonuç 3\'tür.'),
  ('Altın oran araması (golden-section search), üçlü aramaya göre her adımda neyi tasarruf eder?', 'Önceki adımdaki iç noktalardan birini yeniden kullanarak bir fonksiyon değerlendirmesi', ['Aralığı her adımda tam yarıya indirerek bir karşılaştırma', 'Fonksiyonun türevini hesaplamaya gerek bırakmayarak her adımda bir bölme işlemini', 'Aralığın iki ucunu da sabit tutarak bütün değerlendirmeleri'], 'İç noktalar altın oranla seçildiğinde, aralık daraldıktan sonra eski iç noktalardan biri yeni aralığın iç noktası olur; her adımda yalnız bir yeni değer hesaplanır.'),
  ('Tam sayılar üzerinde üçlü aramayla en büyük değer aranırken aralık birkaç elemana inince (ör. üst − alt < 3) neden kalan konumlar tek tek denetlenir?', 'Çok küçük aralıkta iç noktalar çakışıp aralık daralmayabileceği için', ['Küçük aralıkta fonksiyon artık tek tepeli olmaktan çıktığı ve birden çok tepe oluştuğu için', 'Tam sayılarda üçe bölme işlemi tanımsız olduğu için', 'Son elemanlar her zaman en büyük değeri verdiği için'], 'Üçte bir uzunluk sıfıra yuvarlanınca iç noktalar uçlarla aynı olur ve döngü ilerlemeyebilir. Birkaç eleman kaldığında doğrudan bakmak hem güvenli hem ucuzdur.'),
  ('Sonsuz bir yolda, sağda mı solda mı olduğu ve uzaklığı bilinmeyen bir kapı aranıyor. Sırayla sağa 1, sola 2, sağa 4, sola 8 birim gidip dönerek arama yapılmasının amacı nedir?', 'Hedef uzaklığa göre toplam yürüyüşü sabit bir çarpanla sınırlamak', ['Her iki yöne de aynı uzaklıkta durarak şansı eşitlemek', 'Kapının her zaman ilk dönüş noktasında bulunmasını ve geri yürümeye hiç gerek kalmamasını sağlamak', 'Yürünecek toplam yolu kapıya olan uzaklıktan daha kısa tutmak'], 'Adımları ikiye katlamak, uzaklık d ne olursa olsun toplam yürüyüşün en fazla yaklaşık 9d olmasını sağlar. Sabit adımla salınım ise d büyüdükçe çok daha uzun sürerdi.'),
  ('1 ile n arasındaki tam sayılardan oluşan n + 1 elemanlı bir dizide en az bir sayı tekrarlıdır. Dizi değiştirilmeden ve ek bellek kullanılmadan, tekrar eden sayı \'değer aralığı üzerinde ikili aramayla\' nasıl bulunur?', 'Ortadaki değere eşit ya da küçük eleman sayısı ortadan fazlaysa tekrar alt yarıdadır', ['Dizi önce sıralanır, ardından yan yana duran eşit elemanlar baştan sona taranarak aranır', 'Her eleman diğer bütün elemanlarla tek tek karşılaştırılır', 'Dizinin ortasındaki eleman her zaman tekrar eden sayı olarak döndürülür'], 'Güvercin yuvası ilkesine göre [1, orta] aralığında orta\'dan fazla eleman varsa tekrar bu aralıktadır. Her adımda dizi bir kez sayılır; toplam süre n log n olur.'),
  ('Birbirinden farklı tam sayılardan oluşan sıralı −3, −1, 1, 3, 5 dizisinde a[i] = i olan bir \'sabit nokta\' (indisler 0\'dan) ikili aramayla aranıyor. a[orta] < orta ise arama hangi yöne gider?', 'Sağa; çünkü soldaki her konumda da a[i] < i olur', ['Sola; çünkü sabit nokta her zaman küçük indislerde bulunur', 'Hiçbir yöne; dizide sabit nokta olamayacağı kesinleşir', 'Dizinin başına; çünkü arama baştan yeniden başlatılmalıdır'], 'Değerler farklı tam sayılar olduğundan a[i] − i soldan sağa azalmaz. a[orta] < orta ise solda da fark negatiftir. Bu dizide a[3] = 3 bulunur.'),
  ('Her elemanın sıralı dizideki yerinden en fazla k konum uzakta olduğu bir \'k-sıralı\' diziyi sıralamak için boyutu k + 1 olan bir min-yığın kullanılıyor. Toplam süre hangi mertebededir?', 'n log k', ['n log n', 'n · k²', 'k log n'], 'Sıradaki en küçük eleman mutlaka ilk k + 1 aday arasındadır. Her eleman yığına bir kez girer ve çıkar; yığın küçük olduğundan her işlem log k sürer.'),
  ('Python 3\'te sorted işlevi doğrudan iki öğe alan bir karşılaştırma işlevi kabul etmez. Eski tarz bir karşılaştırma işlevi nasıl kullanılabilir?', 'functools.cmp_to_key ile anahtar işlevine dönüştürülerek', ['reverse parametresine verilerek', 'Karşılaştırma işlevi sorted\'ın ilk argümanı yapılarak', 'Listenin her elemanı karşılaştırma işleviyle çarpılarak ve sonuç sıralanarak'], 'cmp_to_key, negatif/sıfır/pozitif döndüren bir karşılaştırma işlevini, sıralamanın kullanabileceği bir anahtar nesnesine sarar.'),
  ('Düzlemdeki noktaların dış bükey zarfını bulan Graham taraması algoritması ilk adımda noktaları nasıl sıralar?', 'En alttaki noktaya göre açılarına göre', ['x koordinatının karesine göre', 'Noktaların girilme sırasına göre', 'Orijine olan uzaklıklarına göre büyükten küçüğe'], 'En alttaki (eşitlikte en soldaki) nokta seçilir, diğer noktalar bu noktaya göre yaptıkları açıya göre sıralanır; sonra yığınla tek bir tarama yapılır. Toplam süre sıralama nedeniyle n log n\'dir.'),
  ('Sıralı bir dizide kaç farklı değer olduğu, her değerden sonra üst sınır aramasıyla bir sonraki farklı değere atlanarak sayılıyor. Farklı değer sayısı d ise bu yöntemin süresi nedir?', 'd log n', ['n log n', 'n', 'd²'], 'Her farklı değer için bir ikili arama yapılır. Dizi çok uzun ama farklı değer sayısı azsa (ör. milyon elemanda 5 değer) bu yöntem doğrusal taramadan çok hızlıdır.'),
  ('Paralel ve dağıtık sıralamada kullanılan \'örnekleme sıralaması\' (sample sort) veriyi işlemcilere nasıl böler?', 'Rastgele örnekten seçilen ayırıcı değerlerle aralıklara bölerek', ['Veriyi geliş sırasına göre eşit uzunlukta parçalara bölerek', 'Her işlemciye bütün verinin bir kopyasını göndererek', 'Veriyi yalnız ilk elemanın değerine göre iki parçaya bölerek ve işlemcilere rastgele dağıtarak'], 'Örnekten seçilen ayırıcılar, her işlemciye yaklaşık eşit sayıda eleman düşecek değer aralıklarını belirler. Her işlemci kendi aralığını sıralar; aralıklar sırayla birleştirilince sonuç sıralıdır.'),
  ('Sürekli gelen sayıların o ana kadarki ortancasını her an vermek için iki yığın kullanılıyor: küçük yarı için bir max-yığın, büyük yarı için bir min-yığın. Ortanca nereden okunur?', 'Yığınların kökünden', ['Yalnız min-yığının en son eklenen elemanından', 'İki yığındaki bütün elemanların ortalamasından', 'Max-yığının en alttaki yaprağından'], 'Yığınlar boyları en fazla bir farklı olacak biçimde dengelenir; küçük yarının en büyüğü ve büyük yarının en küçüğü köklerde durur. Ortanca O(1)\'de okunur, her ekleme O(log n) sürer.'),
  ('KMP ile \'ABABC\' kalıbı aranırken (önek-sonek tablosu [0, 0, 1, 2, 0]) metinde \'ABAB\' eşleşmiş, \'C\' konumunda uyuşmazlık olmuştur. Algoritma kalıbın hangi indisinden (0\'dan) karşılaştırmayı sürdürür?', '2', ['0', '4', '1'], 'Uyuşmazlıktan önceki konumun tablo değeri 2\'dir: eşleşmiş \'ABAB\'ın son iki harfi \'AB\', kalıbın başıyla aynıdır. Bu yüzden kalıp kaydırılır ve aynı metin karakteri kalıbın 2. indisindeki \'A\' ile karşılaştırılır.'),
  ('Boyer–Moore algoritmasındaki \'iyi sonek\' kuralı uyuşmazlıktan sonra kaydırmayı neye göre belirler?', 'Eşleşmiş son parçanın kalıpta başka nerede geçtiğine göre', ['Metindeki uyuşmayan karakterin alfabedeki sırasına göre', 'Kalıbın ilk karakterinin metinde kaç kez geçtiğine göre', 'Metnin o ana kadar okunmuş uzunluğunun kalıp uzunluğuna oranına göre'], 'Sağdan sola karşılaştırmada uyuşmazlıktan önce eşleşen sonek, kalıpta solda yeniden geçiyorsa kalıp o tekrar hizalanacak kadar kaydırılır. Algoritma kötü karakter ve iyi sonek kurallarından büyük olan kaydırmayı seçer.'),
  ('Kalıbın durumlarını makine sözcüğünün bitlerinde tutup kaydırma ve VEYA işlemleriyle arayan, \'agrep\' aracında da kullanılan algoritma hangisidir?', 'Bitap (shift-or) algoritması', ['Aho–Corasick algoritması', 'Knuth–Morris–Pratt algoritması', 'Z-algoritması'], 'Bitap, kısa kalıplarda her metin karakteri için birkaç bit işlemi yapar; küçük değişikliklerle hatalı (yaklaşık) eşleşmeleri de bulabilir.'),
  ('Bir metindeki en uzun tekrar eden alt dizgeyi bulmak için sonek dizisi kullanılıyor. Sıralı sonekler arasında nereye bakmak yeterlidir?', 'Komşu soneklerin ortak önek uzunluklarına', ['Yalnız ilk ve son sonekin ortak önekine', 'Her sonekin uzunluğuna', 'Yalnız en uzun sonekin ilk yarısına ve ikinci yarısına'], 'İki kez geçen bir alt dizge iki farklı sonekin öneki olur; ortak öneki en uzun olan sonekler sıralamada yan yana düşer. \'banana\' için komşu \'ana\' ve \'anana\' en uzun tekrarı (\'ana\') verir.'),
  ('Birleştirmeli sıralamada iki alt dizi birleştirilmeden önce \'solun son elemanı sağın ilk elemanından büyük değil mi?\' denetimi ekleniyor. Bu küçük değişiklik hangi girdide büyük kazanç sağlar?', 'Zaten sıralı ya da sıralıya çok yakın girdide', ['Ters sıralı girdide', 'Bütün elemanları farklı rastgele girdide', 'Yalnız iki elemanlı girdide'], 'Koşul sağlanırsa iki parça zaten doğru sıradadır ve birleştirme atlanır. Sıralı girdide her düzeyde yalnız bir karşılaştırma yapılır ve toplam süre doğrusala iner.'),
  ('Bir dizinin elemanları ve yan yana dikilmiş çubukların boyları olarak düşünülüyor; iki çubuk ile aradaki zemin arasında en çok su tutan çift, iki uçtan başlayan işaretçilerle aranıyor. Her adımda hangi işaretçi içeri kaydırılır?', 'Kısa çubuğu gösteren işaretçi', ['Uzun çubuğu gösteren işaretçi', 'Her adımda iki işaretçi birden', 'Su miktarı artmışsa sol, azalmışsa sağ işaretçi'], 'Tutulan su kısa çubuk boyu ile genişliğin çarpımıdır. Uzun çubuğu içeri almak genişliği azaltır ama kısa boyu aşamaz; ancak kısa çubuğu değiştirmek daha iyi bir sonuç umudu verir.'),
  ('Bir sıralı dizide aranan değer bulunamadığında, programın aranan değerden büyük ilk elemanı göstermesi isteniyor. Kapalı aralıklı standart ikili arama döngüden çıktığında bu elemanın indisi hangi değişkende bulunur?', 'alt', ['üst', 'orta', 'üst − alt'], 'Döngü alt > üst olduğunda biter; bu anda alt, aranan değerden büyük ilk elemanı, üst ise küçük son elemanı gösterir. Bu yüzden ekleme yeri alt\'tır.'),
  ('Bir Shell sıralaması gerçekleştirmesi 1, 4, 13, 40, 121, … (h ← 3h + 1) dizisinden yalnız n/3\'ü aşmayan boşlukları büyükten küçüğe kullanıyor. n = 100 için hangi boşluklar kullanılır?', '13, 4, 1', ['40, 13, 4, 1', '50, 25, 12, 6, 3, 1', '121, 40, 13, 4, 1'], '100/3 ≈ 33 olduğundan 40 kullanılmaz; en büyük boşluk 13\'tür. Sıralama 13, 4 ve 1 boşluklu üç turla yapılır.'),
  ('Sayma sıralamasında birikimli sayaçlar yerine her değerin çıktıdaki başlangıç konumu (kendinden küçüklerin sayısı) hesaplanıyor. Kararlılığın korunması için yerleştirmede girdi hangi yönde taranmalıdır?', 'Baştan sona; her yerleştirmeden sonra başlangıç konumu bir artırılır', ['Sondan başa; her yerleştirmeden sonra konum bir azaltılır', 'Rastgele sırayla; sonuç yine aynı olur', 'Ortadan iki uca doğru; konum değiştirilmez ve eşitler aynı göze yazılır'], 'Her değerin bölgesi soldan sağa dolar; girdi de soldan okununca eşit değerler ilk sıralarıyla yerleşir. Sondan başa tarama ise bitiş konumları kullanıldığında doğrudur.'),
  ('Negatif ve pozitif tam sayıların karışık olduğu bir dizi onluk LSD taban sıralamasıyla sıralanacak. Yaygın ve basit çözüm hangisidir?', 'Negatifleri ve pozitifleri ayrı sıralayıp negatifleri ters çevirerek öne koymak', ['Eksi işaretini yok sayıp mutlak değerlere göre tek seferde sıralamak', 'Bütün sayıları 10\'a bölüp kalanlarına göre sıralamak', 'Sıralamayı en anlamlı basamaktan başlatıp işareti en sona bırakmak ve sonucu olduğu gibi kullanmak'], 'Mutlak değere göre sıralanan negatifler ters sırada olur (−3, −7 değil −7, −3 gelmelidir). İki grup ayrı işlenip negatifler ters çevrilerek pozitiflerin önüne eklenir; alternatif olarak bütün sayılara sabit bir değer eklenebilir.'),
  ('İkili gösterimde en anlamlı bitten başlayıp her biti hızlı sıralamadaki gibi bir bölümleme ölçütü olarak kullanan (0\'lar sola, 1\'ler sağa) sıralama türüne ne ad verilir?', 'Taban değiş tokuş sıralaması (radix exchange sort)', ['Sayma sıralaması', 'Tek-çift transpozisyon sıralaması', 'Kova sıralaması (eşit genişlikli kovalarla, bit değerine bakmadan)'], 'Her bit düzeyinde dizi iki parçaya ayrılır ve her parça bir sonraki bite göre özyinelemeli olarak bölümlenir; pivot karşılaştırması yerine bit değerine bakılır.'),
  ('Kenneth Batcher\'ın 1968\'de bitonik sıralamayla birlikte önerdiği, karşılaştırıcılarla kurulan bir başka sıralama ağı hangisidir?', 'Tek-çift birleştirmeli sıralama (odd–even merge sort)', ['Kabarcık sıralaması ağı', 'Gözleme sıralaması', 'Sayma sıralaması ağı (her hatta bir sayaç bulunan paralel devre)'], 'Batcher\'ın tek-çift birleştirme ağı da n log² n mertebesinde karşılaştırıcı ve log² n mertebesinde derinlik kullanır; bitonik ağdan biraz daha az karşılaştırıcı gerektirir.'),
  ('Bir program diziyi \'rastgele karşılaştırıcı\' ile sıralayarak karıştırmaya çalışıyor: her karşılaştırmada yazı-tura atıp \'küçük\' ya da \'büyük\' diyor. Bu yöntemin sorunu nedir?', 'Sonuç dağılımı eşit olmaz; kullanılan sıralama algoritmasına göre yanlıdır', ['Bu yöntem hiçbir zaman sonlanmaz', 'Dizi her zaman başlangıçtaki sırasında kalır', 'Yöntem tamamen doğrudur; tek kusuru Fisher–Yates karıştırmasından çok daha yavaş çalışmasıdır'], 'Tutarsız karşılaştırıcı sıralamanın varsayımlarını bozar; bazı elemanların yerinde kalma olasılığı ötekilerden yüksek olur. Doğru karıştırma için Fisher–Yates ya da her elemana rastgele anahtar verip sıralamak kullanılmalıdır.'),
  ('Pivot her seferinde medyanların medyanı yöntemiyle tam ortanca seçilirse hızlı sıralamanın en kötü durumu n log n\'e iner. Bu sürüm uygulamada neden pek kullanılmaz?', 'Ortancayı bulmanın sabit çarpanı büyük olduğundan ortalamada yavaş kalır', ['Bu sürüm yanlış sonuç verdiği için', 'Ortanca pivot dizinin kararlılığını garanti ettiği için ek takaslar gerekir ve algoritma yavaşlar', 'Bu sürüm yalnız 2\'nin kuvveti boyundaki dizilerde çalışabildiği için'], 'Her bölümleme öncesinde doğrusal ama pahalı bir seçim algoritması çalışır. Rastgele ya da üçün ortancası pivotla ortalama durum çok daha hızlıdır; en kötü durum güvencesi için introsort tercih edilir.'),
  ('Satır ve sütunları artan sıralı bir matriste x\'ten küçük eleman sayısı, sol alt köşeden başlayan merdiven taramasıyla sayılıyor. Eleman x\'ten küçükse ne yapılır?', 'O sütunda o satıra kadarki bütün elemanlar sayılır ve sağa geçilir', ['Yalnız o eleman sayılır ve yukarı çıkılır', 'Hiçbir şey sayılmadan aşağı inilir', 'O satırdaki bütün elemanlar birden sayılır ve bir sütun sola geçilerek tarama sürdürülür'], 'Sol alttan başlanırsa küçük bir elemanın üstündeki her eleman da ondan küçüktür; satır + 1 kadar eleman bir kerede sayılır. Böylece m + n adımda sayım biter.'),
  ('Ortalama uzunluğu L karakter olan n sözcükten oluşan sıralı bir listede ikili aramayla bir sözcük aranıyor. Toplam karakter karşılaştırması en kötü durumda hangi mertebededir?', 'L · log n', ['log n', 'n · L', 'L² · n'], 'İkili arama log n sözcük karşılaştırması yapar; ama her sözcük karşılaştırması ortak önek uzunluğuna bağlı olarak L karaktere kadar sürebilir.'),
  ('Python\'da büyük-küçük harfe duyarsız karşılaştırma için str.lower yerine str.casefold kullanılmasının nedeni nedir?', 'Bazı dillerdeki özel harfleri de eşleşecek biçime getirmesi', ['casefold\'un metni alfabetik sıraya dizmesi', 'casefold\'un yalnız Türkçe harfleri dönüştürmesi', 'casefold metni ters çevirip karşılaştırmayı hızlandırdığı ve sonucu önbelleğe aldığı için daha verimlidir'], '\'straße\'.lower() \'straße\' kalırken \'STRASSE\'.lower() \'strasse\' olur ve eşleşmez; casefold ise ikisini de \'strasse\' yapar. Türkçe i/ı dönüşümü için ise yine dile özgü işlem gerekir.'),
  ('3, 30, 34, 5, 9 sayıları yan yana yazılarak oluşturulabilecek en büyük sayı isteniyor. Sayılar metin olarak a ile b karşılaştırılırken \'a + b ile b + a\'dan büyük olan önce gelir\' kuralıyla sıralanırsa sonuç nedir?', '9534330', ['9534303', '3033459', '9533430'], '\'3\' ile \'30\' için \'330\' > \'303\' olduğundan 3 önce gelir. Bu karşılaştırıcıyla sıra 9, 5, 34, 3, 30 olur ve birleşim 9534330\'dur.'),
  ('C++\'ta std::sort\'a karşılaştırıcı olarak \'<\' yerine \'<=\' veren bir işlev verilirse ne olur?', 'Katı zayıf sıralama koşulu bozulur; tanımsız davranış oluşabilir', ['Dizi azalan sırada sıralanır', 'Eşit elemanlar her zaman özgün sıralarında kalır', 'Sıralama her durumda doğru sonuç verir, yalnız eşitlikler yüzünden biraz yavaşlar'], 'std::sort, comp(a, a)\'nın yanlış olmasını bekler. \'<=\' eşit elemanlar için doğru döndürdüğünden algoritma dizinin dışına taşabilir ya da çökebilir.'),
  ('JavaScript\'te dizi.sort((a, b) => a > b) biçiminde, sayı yerine true/false döndüren bir karşılaştırıcı kullanılıyor. Sorun nedir?', 'true/false 1 ve 0\'a dönüşür; \'küçük\' anlamındaki negatif değer hiç üretilmez', ['Karşılaştırıcı yalnız metinlerle çalışır', 'Dizi her zaman ters sıraya dizilir', 'Sıralama işlemi diziyi kopyalayıp özgün diziyi hiç değiştirmeden bırakır ve sonuç kaybolur'], 'sort, karşılaştırıcıdan negatif, sıfır ya da pozitif bir sayı bekler. Yalnız 1 ve 0 alınca \'a < b\' ile \'a = b\' ayırt edilemez ve sonuç motora göre yanlış olabilir; doğru yazım (a, b) => a − b\'dir.'),
  ('Knuth, yerine koyma seçiminin rastgele girdide belleğin iki katı uzunlukta koşular ürettiğini dairesel bir yolda dolaşan bir araç benzetmesiyle açıklar. Bu benzetmedeki araç hangisidir?', 'Kar küreme aracı', ['Çöp kamyonu', 'Posta arabası', 'Yolcu otobüsü'], 'Kar yola düzgün yağarken araç dolaşıp karı kürer; denge durumunda yolun önündeki kar miktarı, araç arkasında kalan kısmın iki katıdır. Bu, koşu uzunluğunun bellek boyunun iki katı olmasına karşılık gelir.'),
  ('7 elemanlı sıralı bir dizide bütün elemanların aranma olasılığı eşitse, başarılı bir ikili aramanın ortalama karşılaştırma sayısı kaçtır?', '17/7 ≈ 2,43', ['3', '7/2 = 3,5', '2'], '1 eleman 1, 2 eleman 2, 4 eleman 3 karşılaştırmayla bulunur: (1 + 4 + 12)/7 = 17/7. Ortalama, en kötü durumdaki 3\'e oldukça yakındır.'),
  ('\'banana\$\' metninin döndürmeleri sözlük sırasına dizilip (\'\$\' harflerden önce gelir) her birinin son karakteri alınıyor. Elde edilen Burrows–Wheeler çıktısı nedir?', 'annb\$aa', ['\$banana', 'aaabnn\$', 'bnn\$aaa'], 'Sıralı döndürmeler \$banana, a\$banan, ana\$ban, anana\$b, banana\$, na\$bana, nana\$ba\'dır; son karakterleri sırayla a, n, n, b, \$, a, a\'dır.'),
  ('Rastgele karıştırılmış n farklı elemanlı bir dizide beklenen ters çift sayısı n(n − 1)/4\'tür. 10 elemanlı rastgele bir dizide eklemeli sıralamanın beklenen kaydırma sayısı kaçtır?', '22,5', ['45', '10', '90'], 'Her eleman çifti 1/2 olasılıkla ters sıradadır; 45 çiftin yarısı 22,5\'tir. Eklemeli sıralama her ters çift için bir kaydırma yaptığından beklenen kaydırma sayısı da 22,5\'tir.'),
  ('Tony Hoare, hızlı sıralamayla birlikte k. en küçük elemanı bulan algoritmayı da yayımlamıştır. Bugün hızlı seçme denen bu algoritmanın Hoare\'un verdiği özgün adı nedir?', 'FIND', ['SEARCH', 'SELECT', 'LOCATE'], 'Hoare 1961\'de Communications of the ACM\'de QUICKSORT ile birlikte FIND algoritmasını yayımladı; bu algoritma bugün quickselect olarak bilinir.'),
  ('JavaScript\'te [NaN].includes(NaN) true, [NaN].indexOf(NaN) ise −1 döndürür. Bu farkın nedeni nedir?', 'includes NaN\'ı kendine eşit sayan bir karşılaştırma, indexOf ise katı eşitlik (===) kullanır', ['includes diziyi sıralayıp ikili arama yapar', 'indexOf yalnız metinlerde çalışır', 'includes diziyi kopyalayıp sondan başa doğru arar ve bu yüzden her zaman farklı bir sonuç bulur'], 'NaN === NaN yanlıştır; bu yüzden indexOf NaN\'ı hiçbir zaman bulamaz. includes ise \'SameValueZero\' karşılaştırmasıyla NaN\'ı NaN\'a eşit kabul eder.'),
  ('Ekranda aynı görünen \'é\' harfi bir metinde tek karakter (U+00E9), ötekinde \'e\' + birleşen vurgu işareti olarak saklanmış. Arama öncesinde iki metne ne uygulanmalıdır?', 'Aynı Unicode normalleştirme biçimi', ['Büyük harfe dönüştürme', 'Metinleri ters çevirme', 'Boşlukları silme ve karakterleri alfabetik dizme'], 'Unicode\'da aynı karakter farklı kod dizileriyle yazılabilir. Normalleştirme iki gösterimi tek biçime getirir; yapılmazsa karakter karşılaştırması eşleşmeyi kaçırır.'),
  ('Yalnız \'<\' karşılaştırması kullanan (eşitliği her adımda denetlemeyen) ikili arama, aranan değerin bulunup bulunmadığını ne zaman anlar?', 'Döngü bittikten sonra kalan tek konumu bir kez denetleyerek', ['Her adımda iki karşılaştırma yaparak', 'Hiçbir zaman anlayamaz, yalnız ekleme yerini verir', 'Dizinin ilk ve son elemanına bakarak, döngüye hiç girmeden ve tek karşılaştırmayla'], 'Döngü her adımda yalnız bir karşılaştırma yaparak aralığı tek konuma indirir; eşitlik en sonda bir kez sınanır. Bu, adım başına karşılaştırmayı azaltır ve ilk eşleşmeyi bulur.'),
  ('Alt sınır (lower bound) araması için alt ve üst değişkenleri kullanan bir döngüde \'a[0..alt − 1] < x ve a[üst..n − 1] ≥ x\' değişmezi korunuyor. Döngü alt = üst olunca bittiğinde alt ne gösterir?', 'x\'ten küçük olmayan ilk elemanın indisini', ['x\'ten küçük son elemanın indisini', 'x\'in dizide geçme sayısını', 'Dizinin ortasındaki elemanın indisini, çünkü aralık hep ortadan bölünür'], 'alt = üst olduğunda solundaki her eleman x\'ten küçük, kendisi ve sağındakiler x\'ten küçük değildir; bu tam olarak alt sınır tanımıdır.'),
  ('Sıralı 2, 3, 4, 7, 11 dizisinde, dizide bulunmayan pozitif tam sayılardan 5.\'si isteniyor. a[i] − i − 1 değeri o konuma kadar eksik sayı adedini verdiğine göre (indisler 0\'dan) sonuç kaçtır?', '9', ['8', '10', '6'], 'Eksik sayılar 1, 5, 6, 8, 9, 10, …\'dur; 5.\'si 9\'dur. İkili aramayla eksik sayısı 5\'ten az olan son konum (a[3] = 7, eksik 3) bulunur ve 7 + (5 − 3) = 9 hesaplanır.'),
  ('C++11 standardı std::sort için karşılaştırma sayısında hangi şartı koyar ve bu şart hangi tür gerçekleştirmeyi zorunlu kılar?', 'En kötü durumda O(n log n); düz hızlı sıralama yerine içgözlemli sıralama gibi yöntemler', ['Ortalama O(n²); kabarcık sıralaması kullanılmasını', 'En kötü durumda O(n); sayma sıralaması kullanılmasını', 'Hiçbir şart koymaz; hangi algoritmanın kullanılacağına her derleyici kendi belgesinde serbestçe karar verir'], 'C++03 yalnız ortalama n log n isterdi. C++11 en kötü durumu da sınırladığından karesel düşebilen basit hızlı sıralama yeterli olmaz; yaygın gerçekleştirmeler introsort kullanır.'),
  ('Linux çekirdeğinin genel amaçlı sort() işlevi hangi algoritmayı kullanır ve bunun gerekçesi nedir?', 'Yığın sıralaması; ek bellek istemez ve en kötü durum süresi sınırlıdır', ['Kabarcık sıralaması; kodu en kısadır', 'Birleştirmeli sıralama; kararlılık zorunludur', 'Sayma sıralaması; çekirdekteki bütün anahtarlar küçük sayılar olduğu için en hızlı yöntem budur'], 'Çekirdek kodunda yığın taşması riski ve öngörülemeyen gecikme istenmez; yığın sıralaması özyinelemesiz, yerinde ve her durumda n log n çalışır.'),
  ('C\'deki qsort, aynı algoritmayı kullansa bile C++\'taki std::sort\'tan genellikle yavaş çalışır. Başlıca nedeni nedir?', 'qsort her karşılaştırmada işlev işaretçisiyle çağrı yapar; std::sort karşılaştırıcıyı satır içine alabilir', ['qsort her zaman kabarcık sıralaması kullanır', 'std::sort çok çekirdekli çalışmak zorundadır', 'qsort diziyi her adımda baştan yeniden kopyaladığı için bellek kullanımı iki katına çıkar ve önbellek boşalır'], 'std::sort şablon olduğu için karşılaştırıcı derleme zamanında bilinir ve doğrudan koda gömülür. qsort ise void işaretçileri ve dolaylı işlev çağrılarıyla çalışır.'),
  ('Python 3.11 ile birlikte list.sort\'ta (Timsort) hangi bölüm değiştirilmiştir?', 'Koşuların hangi sırayla birleştirileceğini belirleyen kural', ['Algoritmanın tamamı hızlı sıralamayla değiştirildi', 'Sıralama kararsız hâle getirildi', 'Anahtar parametresi (key) kaldırıldı ve yerine yalnız iki öğe alan eski tip karşılaştırma işlevi geri getirildi'], 'Koşu bulma ve birleştirme aynı kaldı; yığında bekleyen koşuların birleştirme sırası, daha dengeli birleştirmeler sağlayan powersort kuralıyla belirlenmeye başlandı.'),
  ('DNA dizilerinde (yalnız A, C, G, T harfleri) kalıp aranırken Horspool algoritmasının kaydırmaları neden genellikle kısa kalır?', 'Alfabe çok küçük olduğundan metindeki karakter kalıbın sonuna yakın bir yerde çoğunlukla bulunur', ['DNA dizileri sıralı olduğundan kaydırma gerekmez', 'Horspool algoritması yalnız sayılarla çalışır', 'DNA dizilerinde kalıp hemen her zaman metnin başında bulunur ve arama ilk birkaç karşılaştırmada biter'], 'Kötü karakter kuralı, metindeki karakterin kalıpta en son nerede geçtiğine bakar. Dört harfli alfabede her harf kalıpta büyük olasılıkla geçtiğinden atlamalar küçüktür; bu yüzden başka yöntemler tercih edilir.'),
  ('Pozitif IEEE 754 kayan noktalı sayıların bit desenleri işaretsiz tam sayı gibi karşılaştırılırsa ne olur?', 'Sıra korunur; bu yüzden tam sayı taban sıralaması kullanılabilir', ['Sıra tamamen tersine döner', 'Sıra rastgele olur', 'Yalnız tam sayı değerli olanların sırası korunur, kesirli değerlerin sırası bozulur'], 'Üs alanı anlamlı kısımdan önce gelir ve üs yanlı (biased) saklanır; pozitif sayılarda büyük sayı büyük bit desenine karşılık gelir. Negatif sayılar için bitlerin ayrıca çevrilmesi gerekir.'),
  ('Sıralı bir dizide art arda yapılan aramalarda hedefler birbirine yakınsa, her aramaya son bulunan konumdan başlayıp üstel aramayla ilerlemenin (parmak araması) kazancı nedir?', 'Arama süresi dizi boyuna değil iki hedef arasındaki uzaklığa bağlı olur', ['Dizinin sıralı olması gerekmez', 'Her arama sabit sürede, tek karşılaştırmayla biter', 'Aranan değerler bulunamazsa diziye otomatik olarak doğru yerlerine eklenir ve dizi büyür'], 'Önceki konumdan d uzaklıktaki hedef, üstel adımlarla O(log d) sürede bulunur. Hedefler yakın olduğunda bu, her seferinde baştan O(log n) ikili aramadan hızlıdır.'),
  ('n × n\'lik bir ızgarada komşularından küçük olmayan bir \'tepe\' hücre aranırken, orta sütunun en büyük elemanı bulunup sağ ve sol komşusuyla karşılaştırılıyor. Bu yöntemin süresi hangi mertebededir?', 'n log n', ['n²', 'log n', 'n'], 'Her adımda bir sütun taranır (n iş) ve büyük komşu hangi yandaysa o yarıya geçilir; sütun sayısı her adımda yarıya indiğinden log n adım vardır.'),
  ('İkili aramada her adımda ortadaki eleman yerine aralıktan rastgele bir eleman seçilirse ne olur?', 'Arama yine doğru çalışır; beklenen adım sayısı artar ama logaritmik kalır', ['Arama artık doğru sonuç vermez', 'Adım sayısı her zaman yarıya iner', 'Arama doğrusal aramaya eşdeğer hâle gelir ve her durumda n adım sürer, çünkü eleme yapılamaz'], 'Seçilen eleman hangisi olursa olsun yanlış taraf atılır, bu yüzden sonuç doğrudur. Beklenen adım sayısı yaklaşık 2 ln n ≈ 1,39 log₂ n\'dir.'),
  ('Pratt\'ın 2ᵖ·3ᵠ biçimindeki sayılardan (1, 2, 3, 4, 6, 8, 9, 12, …) oluşan boşluk dizisiyle Shell sıralamasının en kötü durum süresi hangi mertebededir?', 'n log² n', ['n²', 'n', 'n^1,5'], 'Pratt dizisi bilinen en iyi en kötü durum sınırını verir; ama boşluk sayısı çok olduğundan pratikte Ciura gibi dizilerden yavaş çalışır.'),
  ('Birleştirmeli sıralamanın bazı gerçekleştirmelerinde iki dizi dönüşümlü olarak kaynak ve hedef rolüyle kullanılır (\'ping-pong\'). Bunun kazancı nedir?', 'Her birleştirmeden sonra sonucu geri kopyalama zorunluluğu ortadan kalkar', ['Birleştirme için ek bellek gereksinimi tamamen ortadan kalkar ve sıralama yerinde yapılır', 'Algoritma kararsız hâle gelir ve hızlanır', 'Karşılaştırma sayısı yarıya iner'], 'Bir düzeyde A\'dan B\'ye, sonraki düzeyde B\'den A\'ya birleştirilir; her düzeyde fazladan kopyalama yapılmaz. Ek dizi yine gereklidir.'),
  ('Yığın sıralamasında ikili yığın yerine her düğümün d çocuğu olduğu d\'li yığın kullanılırsa ne değişir?', 'Ağaç yüksekliği log_d n\'e iner ama her düzeyde d çocuk karşılaştırılır', ['Algoritma kararlı hâle gelir', 'Ek bellek gereksinimi d katına çıkar, çünkü her düğüm için d ayrı dizi tutulur', 'Algoritma en kötü durumda doğrusal sürede çalışır'], 'Süzme sırasında her düzeyde en büyük çocuğu bulmak için d − 1 karşılaştırma gerekir. Daha sığ ağaç yer değiştirme sayısını azaltır; uygun d seçimi önbellek kullanımını da iyileştirebilir.'),
  ('Uzunlukları farklı dizgeler LSD taban sıralamasıyla sıralanacak. Kısa dizgeler nasıl ele alınır?', 'Sağ uçları alfabedeki her karakterden küçük bir dolgu karakteriyle tamamlanır', ['Kısa dizgeler sıralamadan çıkarılır', 'Kısa dizgeler sol baştan, ilk karakterlerinin önüne eklenen dolgu karakterleriyle tamamlanır', 'Bütün dizgeler en kısa dizgenin uzunluğuna kısaltılır'], 'Sözlük sırasında \'ar\' \'ara\'dan önce gelir; eksik konum en küçük karakter gibi davranmalıdır. Dolgu sağa eklenince bu sağlanır.'),
  ('Dış sıralamada aynı anda birleştirilen koşu sayısı (k) artırıldıkça birleştirme turu azalır. k\'yi aşırı büyütmenin sakıncası nedir?', 'Her koşuya düşen okuma tamponu küçülür ve disk erişim sayısı artar', ['Birleştirme sonucu yanlış sıralanır', 'Koşular kararsız hâle gelir', 'Tur sayısı yeniden artmaya başlar ve bazı koşular birleştirme sırasında kaybolur'], 'Bellek k tampona bölünür; tamponlar küçüldükçe her koşudan küçük parçalar okunur ve çok sayıda ayrı disk erişimi gerekir. En iyi k, tur sayısı ile tampon boyu arasında bir dengedir.'),
  ('Komşu elemanları arasındaki fark en fazla 1 olan 4, 5, 6, 7, 6 dizisinde 6 aranıyor. Arama 0. indisten başlayıp her adımda |6 − a[i]| kadar ileri atlıyor. Sırasıyla hangi elemanlara bakılır?', '4, 6', ['4, 5, 6', '4, 7, 6', '6'], 'a[0] = 4 olduğundan 6\'ya en az 2 adım uzaklıktadır; 2 konum atlanır ve a[2] = 6 bulunur. Komşu farkı en fazla 1 olduğundan atlanan konumlarda hedef bulunamaz.'),
  ('Dış sıralamada çok sayıda koşuyu birleştirirken her adımda yalnız bir kök-yol güncellemesiyle en küçüğü bulan, iç düğümlerde kaybedenleri tutan yapıya ne ad verilir?', 'Kaybedenler ağacı (loser tree)', ['İkili arama ağacı', 'Önek ağacı (trie)', 'Sonek dizisi (sıralı sonekler)'], 'Kazananlar ağacına benzer, ama her iç düğüm o maçın kaybedenini tutar; yeni eleman geldiğinde yalnız yaprağından köke giden yoldaki karşılaştırmalar yapılır.'),
  ('Timsort\'un birleştirme sırasında \'dörtnala\' moduna geçmesi için bir koşudan art arda kaç eleman seçilmesi gerektiğini belirleyen başlangıç eşiği (MIN_GALLOP) kaçtır?', '7', ['2', '32', '64'], 'Bir koşu art arda 7 kez kazanırsa üstel arama moduna geçilir. Eşik, dörtnala modunun yararlı ya da zararlı olmasına göre çalışma sırasında uyarlanır.'),
  ('Sedgewick\'in önerdiği bir hızlı sıralama iyileştirmesinde, boyu belli bir eşiğin altına inen alt diziler hiç sıralanmadan bırakılır. Sıralama nasıl tamamlanır?', 'En sonda bütün diziye tek bir eklemeli sıralama geçişi yapılarak', ['Küçük alt diziler silinerek', 'Her küçük alt dizi ayrı ayrı yığın sıralamasıyla sıralanarak', 'Dizinin tamamı en sonda yeniden hızlı sıralamayla baştan sıralanarak'], 'Bölümlemeler bitince dizi neredeyse sıralıdır: her eleman kendi küçük parçasının içindedir. Eklemeli sıralama bu durumda çok az kaydırmayla diziyi doğrusala yakın sürede tamamlar.'),
  ('Üçün ortancası pivot seçiminde ilk, orta ve son eleman kendi aralarında sıralanıp yerlerine konursa bölümleme döngüsü için hangi ek kolaylık sağlanır?', 'Uçlardaki elemanlar gözcü görevi görür ve dizi sınırı denetimine gerek kalmaz', ['Pivot her durumda dizinin tam ortancası olur ve bölümleme her seferinde diziyi iki eşit parçaya ayırır', 'Bölümleme kararlı hâle gelir', 'Dizinin geri kalanı da kendiliğinden sıralanır'], 'Sol uçta pivottan küçük olmayan, sağ uçta pivottan büyük olmayan birer eleman bulunduğu için işaretçiler dizinin dışına taşamaz; iç döngülerdeki sınır karşılaştırmaları atlanabilir.'),
  ('Karşılaştırmaya dayalı sıralamalar için n log n alt sınırı yalnız en kötü durum için mi geçerlidir?', 'Hayır; ortalama durumda da yaklaşık n log n karşılaştırma gerekir', ['Evet; ortalama durumda doğrusal süre mümkündür', 'Evet; ortalama durumda sabit süre yeterlidir', 'Hayır; ortalama durumda bile n² karşılaştırma zorunludur, çünkü her çift en az bir kez karşılaştırılmalıdır'], 'Karar ağacının n! yaprağının ortalama derinliği de log₂ n! ≈ n log₂ n mertebesindedir; bu yüzden hiçbir karşılaştırmalı algoritma ortalamada da bu sınırın altına inemez.'),
];
